class Solution {
 int target,best;vector<int> top;
 void dfs(int i,int cost){
  if(abs(cost-target)<abs(best-target) || (abs(cost-target)==abs(best-target)&&cost<best))best=cost;
  if(i==(int)top.size())return;
  dfs(i+1,cost);dfs(i+1,cost+top[i]);dfs(i+1,cost+2*top[i]);
 }
public:
 int closestCost(vector<int>& baseCosts,vector<int>& toppingCosts,int t){
  target=t;top=toppingCosts;best=INT_MAX;
  for(int b:baseCosts)dfs(0,b);
  return best;
 }
};
